import * as Clipboard from "expo-clipboard";
import * as WebBrowser from "expo-web-browser";
import type { Href } from "expo-router";
import { Platform, Share } from "react-native";

export { libraryWebUrl } from "./exits-url";

// The reader's exits (plan 05 §R4, owner decision (a) 2026-10-15). Both are
// NAVIGATION, never content: free and unmetered — the library page enforces
// its own tier. No exit ever points at pricing or checkout.

/** The reader route for citation `n` of workspace item `itemId`. Cast: the
 *  typed-routes manifest is regenerated by `expo start`, not by tsc. */
export function sourceHref(itemId: string, n: number): Href {
  return `/source/${encodeURIComponent(itemId)}/${n}` as Href;
}

function isHttp(url: string): boolean {
  return /^https?:\/\//i.test(url.trim());
}

/** http(s) only, in the in-app browser (plan K3). */
export function openInBrowser(url: string): void {
  if (!isHttp(url)) return;
  WebBrowser.openBrowserAsync(url.trim()).catch(() => undefined);
}

export async function copyLink(url: string): Promise<void> {
  await Clipboard.setStringAsync(url);
}

/** The OS share sheet (it also offers «نسخ» on both platforms). iOS takes the
 *  link as `url`; Android only reads `message`. */
export function shareLink(url: string, title?: string): void {
  const content = Platform.OS === "ios" ? { url, title } : { message: url, title };
  Share.share(content).catch(() => undefined);
}
